import React, { useContext, useState } from 'react';
import Container from 'react-bootstrap/Container';
import Navbar from 'react-bootstrap/Navbar';
import Button from 'react-bootstrap/Button';
import Form from 'react-bootstrap/Form';
import { AppContext } from '../App';
import axios from 'axios';
import { SERVER_URL } from '../config';
import { fetchData } from '../fetchData';

const Auth = () => {
  const { setCurrentUser, registrationToggle, setRegistrationToggle } =
    useContext(AppContext);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');

  const submitRegistration = async e => {
    e.preventDefault();
    try {
      const response = await axios.post(`${SERVER_URL}register`, {
        username,
        password,
      });
      // Handle successful registration (you might want to redirect or show a success message)
      console.log('Registration successful:', response.data);

      // Optionally, you can automatically login the user after registration
      submitLogin(e);
    } catch (error) {
      // Handle registration error (display an error message or log the error)
      console.error('Registration failed:', error.response.data);
    }
  };

  const submitLogin = async e => {
    e.preventDefault();
    try {
      const response = await axios.post(`${SERVER_URL}login`, {
        password,
      });

      // Update the user context or redirect to the authenticated page
      setCurrentUser(response.data.user);

      // Handle successful login (you might want to redirect or show a success message)
      console.log('Login successful:', response.data);
    } catch (error) {
      // Handle login error (display an error message or log the error)
      console.error('Login failed:', error.response.data);
    }
  };

  const updateFormBtn = () => {
    setRegistrationToggle(!registrationToggle);
  };

  return (
    <div>
      <Navbar bg="dark" variant="dark">
        <Container>
          <Navbar.Brand>
            <img
              alt=""
              src="/logo.png"
              width="30"
              height="30"
              className="d-inline-block align-top"
            />{' '}
            LanGuard
          </Navbar.Brand>
          <Navbar.Toggle />
          <Navbar.Collapse className="justify-content-end">
            <Navbar.Text>
              <Button id="form_btn" onClick={updateFormBtn} variant="light">
                Register
              </Button>
            </Navbar.Text>
          </Navbar.Collapse>
        </Container>
      </Navbar>
      {registrationToggle ? (
        <div className="center">
          <Form onSubmit={e => submitRegistration(e)}>
            <Form.Group className="mb-3" controlId="formBasicUsername">
              <Form.Label>Username</Form.Label>
              <Form.Control
                type="text"
                placeholder="Enter username"
                value={username}
                onChange={e => setUsername(e.target.value)}
              />
            </Form.Group>
            <Form.Group className="mb-3" controlId="formBasicPassword">
              <Form.Label>Password</Form.Label>
              <Form.Control
                type="password"
                placeholder="Password"
                value={password}
                onChange={e => setPassword(e.target.value)}
              />
            </Form.Group>
            <Button variant="primary" type="submit">
              Submit
            </Button>
          </Form>
        </div>
      ) : (
        <div className="center">
          <Form onSubmit={e => submitLogin(e)}>
            <Form.Group className="mb-3" controlId="formBasicUsername">
              <Form.Label>Username</Form.Label>
              <Form.Control
                type="text"
                placeholder="Enter username"
                value={username}
                onChange={e => setUsername(e.target.value)}
              />
            </Form.Group>
            <Form.Group className="mb-3" controlId="formBasicPassword">
              <Form.Label>Password</Form.Label>
              <Form.Control
                type="password"
                placeholder="Password"
                value={password}
                onChange={e => setPassword(e.target.value)}
              />
            </Form.Group>
            <Button variant="primary" type="submit">
              Submit
            </Button>
          </Form>
        </div>
      )}
    </div>
  );
};

export default Auth;
